      const normalizeInfoLabel=value=>safeText(value).replace(/[：:]+$/,'').replace(/\s+/g,' ').trim();
      const infoLabelAliases={};
      Object.entries(infoDescriptionByLabel).forEach(([source,description])=>{
        const add=alias=>{const normalized=normalizeInfoLabel(alias);if(normalized)infoLabelAliases[normalized]=description};
        add(source);add(copyMap[source]);
        const row=uxWritingCatalog[uxCopyKey(source)];Object.values(row||{}).forEach(add);
      });
      const infoDescriptionFor=labelNode=>{
        if(!labelNode)return '';
        const remembered=labelNode.dataset.infoLabelSource;if(remembered)return infoDescriptionByLabel[remembered]||infoLabelAliases[normalizeInfoLabel(remembered)]||'';
        const raw=normalizeInfoLabel(labelNode.querySelector(':scope > span')?.textContent||labelNode.textContent).replace(/\s+i$/i,'');
        const source=uxCopyKey(raw);return infoLabelAliases[raw]||infoLabelAliases[source]||infoDescriptionByLabel[raw]||'';
      };
      function enhanceInfoTips(){
        // Convert helper copy into a compact, accessible tooltip without
        // changing the field's layout. Keep the original source string on
        // the control so locale switches can update the bubble in place.
        // Legacy helper contract: help.dataset.infoSource||help.textContent
        const attach=(labelNode,help)=>{
          if(!labelNode)return;
          const helper=typeof help==='string'?null:help;
          const source=safeText(typeof help==='string'?help:helper?.dataset.infoSource||helper?.textContent);if(!source)return;
          labelNode.dataset.infoLabelSource=labelNode.dataset.infoLabelSource||normalizeInfoLabel(labelNode.textContent).replace(/\s+i$/i,'');
          let button=labelNode.querySelector(':scope > .info-tip'),bubble=button?.querySelector('.info-tip-popup');
          if(!button){
            button=document.createElement('button');button.type='button';button.className='info-tip';button.setAttribute('aria-label',label('راهنمای فیلد','Field information'));button.setAttribute('aria-expanded','false');button.textContent='i';
            bubble=document.createElement('span');bubble.className='info-tip-popup';bubble.setAttribute('role','tooltip');bubble.id='info-tip-'+Math.random().toString(36).slice(2,10);button.appendChild(bubble);labelNode.appendChild(button);
            button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();button.setAttribute('aria-expanded',button.getAttribute('aria-expanded')!=='true'?'true':'false')});
          }
          button.dataset.infoSource=source;button.setAttribute('aria-label',label('راهنمای فیلد','Field information'));
          const rendered=translatedCopy(source)||source;if(bubble&&bubble.textContent!==rendered)bubble.textContent=rendered;
          const field=labelNode.closest('.field,.appearance-field');
          field?.querySelectorAll(':scope > input,:scope > select,:scope > textarea').forEach(control=>{let ids=String(control.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean);if(helper?.id)ids=ids.filter(id=>id!==helper.id);if(bubble&&!ids.includes(bubble.id))control.setAttribute('aria-describedby',[...ids,bubble.id].join(' '))});
          if(helper?.parentElement)helper.remove();
        };
        document.querySelectorAll('.field > label,.appearance-field > label,.appearance-field:not(.full),.check-row,.project-access-heading > label').forEach(labelNode=>{
          // An appearance container can itself carry the `.appearance-field`
          // class while also containing a real label. The real label is the
          // anchor; skipping the container here prevents duplicate i buttons
          // on theme/accent controls. Outer checkbox labels without a nested
          // label are still handled by the same selector.
          if(labelNode.matches('.appearance-field')&&labelNode.querySelector(':scope > label'))return;
          const field=labelNode.matches('.appearance-field')?labelNode:labelNode.closest('.field,.appearance-field');if(!field)return;
          const description=infoDescriptionFor(labelNode),help=field.querySelector(':scope > small.muted');
          if(description)attach(labelNode,description);else if(help)attach(labelNode,help);
          field.querySelectorAll(':scope > input[aria-describedby],:scope > select[aria-describedby],:scope > textarea[aria-describedby]').forEach(control=>String(control.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean).forEach(id=>{const described=document.getElementById(id);if(described&&described!==help&&!description)attach(labelNode,described)}));
        });
        // These schedule notes are section-level helpers rather than inputs.
        // Anchor them to the schedule heading so they also follow the same
        // i/hover interaction and never consume grid space.
        const scheduleHeading=document.querySelector('#view-schedule .schedule-matrix-card .section-title h3');
        ['freshnessWindowHelp','dailyProcessingCapHelp'].forEach(id=>{const help=document.getElementById(id);if(help&&scheduleHeading&&help.parentElement)attach(scheduleHeading,help)});
        document.querySelectorAll('.info-tip').forEach(button=>{const source=button.dataset.infoSource||'';const bubble=button.querySelector('.info-tip-popup');if(source&&bubble){const rendered=translatedCopy(source)||source;if(bubble.textContent!==rendered)bubble.textContent=rendered}});
      }
      // Page-level guidance follows the same reviewed copy contract as field
