      function enhancePageHeadInfo(){
        document.querySelectorAll('.view .page-head').forEach(head=>{
          const view=head.closest('.view'),title=head.querySelector('h2'),description=head.querySelector(':scope > div > p,:scope > p');
          if(!title||!description)return;
          const source=description.dataset.pageInfoSource||pageInfoSources[view?.id]||uxCopyKey(safeText(description.textContent));
          if(!source)return;
          description.dataset.pageInfoSource=source;description.classList.add('page-head-description');
          const titleWrap=title.parentElement;if(!titleWrap)return;titleWrap.classList.add('page-head-title');
          let button=titleWrap.querySelector(':scope > .page-info-tip'),bubble=button?.querySelector('.info-tip-popup');
          if(!button){
            button=document.createElement('button');button.type='button';button.className='info-tip page-info-tip';button.textContent='i';button.setAttribute('aria-expanded','false');
            bubble=document.createElement('span');bubble.className='info-tip-popup';bubble.setAttribute('role','tooltip');bubble.id='page-info-tip-'+Math.random().toString(36).slice(2,10);button.appendChild(bubble);title.insertAdjacentElement('afterend',button);
            button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();button.setAttribute('aria-expanded',button.getAttribute('aria-expanded')!=='true'?'true':'false')});
          }
          button.dataset.infoSource=source;button.setAttribute('aria-label',label('راهنمای صفحه','Page information'));if(bubble)button.setAttribute('aria-describedby',bubble.id);
          const rendered=translatedCopy(source)||source;if(bubble&&bubble.textContent!==rendered)bubble.textContent=rendered;
        });
      }
